def transform(wb):
    ws = wb['Sheet1']
    max_row = ws.max_row
    if max_row is None or max_row < 1:
        return
    cache = cached_values.get('Sheet1', {})
    kept = [1]
    for r in range(2, max_row + 1):
        v = cache.get(f'C{r}')
        if v is None:
            v = ws.cell(row=r, column=3).value
        keep = False
        if v is not None:
            s = str(v).strip().upper()
            if s == '#N/A':
                keep = True
        if keep:
            kept.append(r)
    orig_dims = {}
    for r in range(1, max_row + 1):
        if r in ws.row_dimensions:
            orig_dims[r] = ws.row_dimensions[r]
    for r in range(max_row, 1, -1):
        if r not in kept:
            ws.delete_rows(r, 1)
    for key in list(ws.row_dimensions.keys()):
        del ws.row_dimensions[key]
    for new_r in range(1, len(kept) + 1):
        orig_r = kept[new_r - 1]
        if orig_r in orig_dims:
            ws.row_dimensions[new_r] = orig_dims[orig_r]
